#!/usr/bin/env python3
"""Deterministic, dependency-free public pages. Product facts live in data/products.json."""
from pathlib import Path
from html import escape as esc
import json
from build_footers import CREDIT

ROOT = Path(__file__).resolve().parents[1]
DATA = json.loads((ROOT / 'data/products.json').read_text())
HOST = 'https://www.techdadclt.com'
